INSERT INTO `material` VALUES (1,1,'Algebra Practice - Linear Equations','Solve these equations:\n1. x + 5 = 12\n2. 2x - 3 = 7\n3. 4x + 2 = 18\n\nAnswers: 1. x=7, 2. x=5, 3. x=4','Generated by EDUCARE AI - Based on Grade 10 Algebra','Approved','2026-04-01 03:42:21',NULL,NULL,NULL,0,0),(2,1,'Algebra Practice - Quadratic Equations','Solve:\n1. x² = 25\n2. x² - 9 = 0\n3. x² + 2x - 8 = 0\n\nAnswers: 1. x=±5, 2. x=±3, 3. x=2 or x=-4','Generated by EDUCARE AI - Based on Grade 10 Algebra','Approved','2026-04-01 03:42:21',NULL,NULL,NULL,0,0),(3,2,'Limits Practice - Introduction','Find the limits:\n1. lim(x?2) (x+3)\n2. lim(x?0) (2x+1)\n3. lim(x?5) (x²-25)/(x-5)\n\nAnswers: 1. 5, 2. 1, 3. 10','Generated by EDUCARE AI - Based on Grade 11 Limits','Approved','2026-04-01 03:42:21',NULL,NULL,NULL,0,0),(4,3,'Integration Practice - Basic Integrals','Find the integrals:\n1. ? 2x dx\n2. ? x² dx\n3. ? 4 dx\n\nAnswers: 1. x² + C, 2. x³/3 + C, 3. 4x + C','Generated by EDUCARE AI - Based on Grade 12 Integration','Rejected','2026-04-01 03:42:21',NULL,NULL,NULL,0,0),(5,3,'Study sheet: Integration (curriculum-grounded)','# Integration\n\n## Curriculum excerpts (retrieved locally from indexed textbook chunks)\n\n1. Here are 10 ideas to help take care of the book: 1.\n\n2. MATHEMATICS STUDENT’S TEXTBOOK GRADE 12 MATHEMATICS MATHEMATICS FEDERAL DEMOCRATIC REPUBLIC OF ETHIOPIA FEDERAL DEMOCRATIC REPUBLIC OF ETHIOPIA MINISTRY OF EDUCATION MINISTRY OF EDUCATION FDRE MoE STUDENT’S TEXTBOOK GRADE 12 STUDENT’S TEXTBOOK GRADE 12\n\n3. This Textbook is the property of your school.\n\n4. Take good care not to damage or lose it.\n\n5. Cover the book with protective materials, such as plastic, old newspapers or magazines.\n\n6. Always keep the textbook in a clear dry place.\n\n7. Be sure your hands are clean when you use the textbook.\n\n8. Do not write on the cover or inside pages.\n\n## Practice (template-based; not generated by an external model)\n\n1. Differentiate a simple polynomial term-by-term (use an expression from the excerpts).\n2. Set up an integral for a simple area problem described in the excerpts.\n\n## How this was built\n\n- Retrieval: local TF-IDF + FAISS over `faiss_index` (Ethiopian curriculum embeddings).\n- Generation: rule-based templates + sentence scoring (no LLM, no API).','Ethiopian curriculum — grade12_math.pdf (p. 1); grade12_math.pdf (p. 2); grade12_math.pdf (p. 302); grade12_math.pdf (p. 304)','Rejected','2026-04-02 10:44:29',NULL,NULL,NULL,0,0),(6,1,'Study sheet: Algebra (curriculum-grounded)','# Algebra\n\n## Curriculum excerpts (retrieved locally from indexed textbook chunks)\n\n1. Here are 10 ideas to help take care of the book: 1.\n\n2. MATHEMATICS STUDENT’S TEXTBOOK GRADE 12 MATHEMATICS MATHEMATICS FEDERAL DEMOCRATIC REPUBLIC OF ETHIOPIA FEDERAL DEMOCRATIC REPUBLIC OF ETHIOPIA MINISTRY OF EDUCATION MINISTRY OF EDUCATION FDRE MoE STUDENT’S TEXTBOOK GRADE 12 STUDENT’S TEXTBOOK GRADE 12\n\n3. This Textbook is the property of your school.\n\n4. Take good care not to damage or lose it.\n\n5. Cover the book with protective materials, such as plastic, old newspapers or magazines.\n\n6. Always keep the textbook in a clear dry place.\n\n7. Be sure your hands are clean when you use the textbook.\n\n8. Do not write on the cover or inside pages.\n\n## Practice (template-based; not generated by an external model)\n\n1. In your own words, summarize the main idea about “Algebra” using the excerpts.\n2. Quote one sentence from the excerpts and explain why it matters.\n3. List two vocabulary terms from the excerpts and define each in one line.\n4. Try this curriculum-style item: 1. Cover the book with protective materials, such as plastic, old\n5. Try this curriculum-style item: 2. Always keep the textbook in a clear dry place.\n\n## How this was built\n\n- Retrieval: local TF-IDF + FAISS over `faiss_index` (Ethiopian curriculum embeddings).\n- Generation: rule-based templates + sentence scoring (no LLM, no API).','Ethiopian curriculum — grade12_math.pdf (p. 1); grade12_math.pdf (p. 2); grade12_math.pdf (p. 302); grade12_math.pdf (p. 304)','Approved','2026-04-02 10:48:53',NULL,NULL,NULL,0,0),(7,1,'Practice: Algebra','<div class=\"rag-explanation\"><h3>Curriculum Overview</h3><p>MATHEMATICS   STUDENT’S TEXTBOOK    GRADE 12\nMATHEMATICS\nMATHEMATICS\nFEDERAL DEMOCRATIC REPUBLIC OF ETHIOPIA\nFEDERAL DEMOCRATIC REPUBLIC OF ETHIOPIA\nMINISTRY OF EDUCATION\nMINISTRY OF EDUCATION\nFDRE\nMoE\nSTUDENT’S TEXTBOOK\nGRADE 12\nSTUDENT’S TEXTBOOK\nGRADE 12</p></div>\n<div class=\"rag-questions\"><h3>Practice Questions</h3><div class=\"rag-question\" data-correct=\"3\"><p><strong>Q1.</strong> Solve the system:  x + y = 11  and  x - y = -7</p><ul class=\"rag-options\"><li data-idx=\"0\" class=\"rag-option\">A. x = 9, y = 2</li><li data-idx=\"1\" class=\"rag-option\">B. x = 3, y = 8</li><li data-idx=\"2\" class=\"rag-option\">C. x = 11, y = -7</li><li data-idx=\"3\" class=\"rag-option\">D. x = 2, y = 9</li></ul><div class=\"rag-answer\" style=\"display:none\"><strong>Answer: D</strong> — Add equations: 2x = 4  →  x = 2;  then y = 11 - 2 = 9</div></div><div class=\"rag-question\" data-correct=\"1\"><p><strong>Q2.</strong> Solve for x:  9x = 126</p><ul class=\"rag-options\"><li data-idx=\"0\" class=\"rag-option\">A. 135</li><li data-idx=\"1\" class=\"rag-option\">B. 14</li><li data-idx=\"2\" class=\"rag-option\">C. 13</li><li data-idx=\"3\" class=\"rag-option\">D. 15</li></ul><div class=\"rag-answer\" style=\"display:none\"><strong>Answer: B</strong> — Divide both sides by 9: x = 126 / 9 = 14</div></div><div class=\"rag-question\" data-correct=\"2\"><p><strong>Q3.</strong> Solve the system:  x + y = 14  and  x - y = 2</p><ul class=\"rag-options\"><li data-idx=\"0\" class=\"rag-option\">A. x = 6, y = 8</li><li data-idx=\"1\" class=\"rag-option\">B. x = 9, y = 5</li><li data-idx=\"2\" class=\"rag-option\">C. x = 8, y = 6</li><li data-idx=\"3\" class=\"rag-option\">D. x = 14, y = 2</li></ul><div class=\"rag-answer\" style=\"display:none\"><strong>Answer: C</strong> — Add equations: 2x = 16  →  x = 8;  then y = 14 - 8 = 6</div></div><div class=\"rag-question\" data-correct=\"3\"><p><strong>Q4.</strong> Solve for x:  5x = 70</p><ul class=\"rag-options\"><li data-idx=\"0\" class=\"rag-option\">A. 65</li><li data-idx=\"1\" class=\"rag-option\">B. 75</li><li data-idx=\"2\" class=\"rag-option\">C. 13</li><li data-idx=\"3\" class=\"rag-option\">D. 14</li></ul><div class=\"rag-answer\" style=\"display:none\"><strong>Answer: D</strong> — Divide both sides by 5: x = 70 / 5 = 14</div></div></div>','grade12_math.pdf, page 1','Approved','2026-04-08 23:54:35',NULL,NULL,NULL,0,0),(8,2,'Practice: Limits','<div class=\"rag-explanation\"><h3>Curriculum Overview</h3><p>MATHEMATICS \nSTUDENT TEXTBOOK \n                         GRADE 10 \nAuthors: \nTadele Mekonnen Yihun (MSc) \nMamo Teketel Mekasha (MSc) \nEditors: \nMohammed Yiha Dawud (PhD)    (Content Editor) \nAkalu Chaka Mekuria (MA)   (Curriculum Editor) \nEndalfer Melese Moges (MA)     (Language Editor) \nIllustrator: \nBahiru Chane Tamiru (MSc) \nDesigner: \n         Aknaw H/mariam Habte (MSc) \nEvaluators: \nDawit Ayalneh Tebkew (MSc) \n          Matebie Alemayehu Wasihun (MED) \n          Mustefa Kedir Edao (BED) \n          Tesfaye Sileshi Chala (MA) \n \n \n \nFEDERAL DEMOCRATIC REPUBLIC OF ETHIOPIA \nMINISTRY OF EDUCATION \n HAWASSA UNIVERSITY</p></div>\n<div class=\"rag-formulas\"><h3>Key Formulas</h3><ul><li><code>below the line  =  .</code></li><li><code>4. The ordered pair (0, 3) satisfies the relation. Hence, points above the line  =</code></li></ul></div>\n<div class=\"rag-questions\"><h3>Practice Questions</h3><div class=\"rag-question\" data-correct=\"0\"><p><strong>Q1.</strong> Evaluate:  lim(x → 0)  sin(3x) / (3x)</p><ul class=\"rag-options\"><li data-idx=\"0\" class=\"rag-option\">A. 1</li><li data-idx=\"1\" class=\"rag-option\">B. 0</li><li data-idx=\"2\" class=\"rag-option\">C. 3</li><li data-idx=\"3\" class=\"rag-option\">D. 1/3</li></ul><div class=\"rag-answer\" style=\"display:none\"><strong>Answer: A</strong> — Using the standard limit lim(u→0) sin(u)/u = 1, with u = 3x, the answer is 1</div></div><div class=\"rag-question\" data-correct=\"1\"><p><strong>Q2.</strong> Evaluate:  lim(x → 3)  (x + 7)</p><ul class=\"rag-options\"><li data-idx=\"0\" class=\"rag-option\">A. 3</li><li data-idx=\"1\" class=\"rag-option\">B. 10</li><li data-idx=\"2\" class=\"rag-option\">C. 7</li><li data-idx=\"3\" class=\"rag-option\">D. 9</li></ul><div class=\"rag-answer\" style=\"display:none\"><strong>Answer: B</strong> — Direct substitution: 3 + 7 = 10</div></div><div class=\"rag-question\" data-correct=\"1\"><p><strong>Q3.</strong> Evaluate:  lim(x → ∞)  (3x + 4) / (1x + 5)</p><ul class=\"rag-options\"><li data-idx=\"0\" class=\"rag-option\">A. 4</li><li data-idx=\"1\" class=\"rag-option\">B. 3</li><li data-idx=\"2\" class=\"rag-option\">C. 3/2</li><li data-idx=\"3\" class=\"rag-option\">D. 4/5</li></ul><div class=\"rag-answer\" style=\"display:none\"><strong>Answer: B</strong> — Divide numerator and denominator by x: limit = 3/1 = 3</div></div><div class=\"rag-question\" data-correct=\"3\"><p><strong>Q4.</strong> Evaluate:  lim(x → 5)  (x + 5)</p><ul class=\"rag-options\"><li data-idx=\"0\" class=\"rag-option\">A. 9</li><li data-idx=\"1\" class=\"rag-option\">B. 11</li><li data-idx=\"2\" class=\"rag-option\">C. 12</li><li data-idx=\"3\" class=\"rag-option\">D. 10</li></ul><div class=\"rag-answer\" style=\"display:none\"><strong>Answer: D</strong> — Direct substitution: 5 + 5 = 10</div></div></div>','grade10_math.pdf, page 3','Approved','2026-04-09 00:28:56',NULL,NULL,NULL,0,0),(9,2,'Practice: Limits','<div class=\"rag-explanation\"><h3>Curriculum Overview</h3><p>MATHEMATICS \nSTUDENT TEXTBOOK \n                         GRADE 10 \nAuthors: \nTadele Mekonnen Yihun (MSc) \nMamo Teketel Mekasha (MSc) \nEditors: \nMohammed Yiha Dawud (PhD)    (Content Editor) \nAkalu Chaka Mekuria (MA)   (Curriculum Editor) \nE